import sys
from math import gcd

def main():
    n, k = map(int, sys.stdin.read().split())
    m = 4 * n
    sets = []

    def find_next_valid_number(existing_numbers):
        candidate = max(existing_numbers) + 1 if existing_numbers else 1
        while True:
            valid = True
            for num in existing_numbers:
                if gcd(candidate, num) != k:
                    valid = False
                    break
            if valid:
                return candidate
            candidate += 1

    for _ in range(n):
        current_set = []
        for _ in range(4):
            current_set.append(find_next_valid_number(current_set))
        sets.append(current_set)

    print(m)
    for s in sets:
        print(*s)

main()
